// Maps a quick-entry text + parsed macros into a nutrition_logs insert
// payload. Mirrors outbox/mapSetLog.ts's isValid*/to*Insert pairing.
//
// `id` is generated by the caller (expo-crypto's randomUUID), not in here —
// keeps this module native-module-free, same reasoning as workout/session.ts:
// expo-crypto transitively pulls in react-native's Flow-typed sources, which
// plain Node/Vitest can't parse.

import type { NutritionLogInsert } from './types';
import { hasAnyMacro, parseQuickEntry, type ParsedMacros } from './parseQuickEntry';
import { localDate } from '../localDate';

export function toNutritionLogInsert(
  id: string,
  userId: string,
  description: string,
  parsed: ParsedMacros = parseQuickEntry(description),
  mealSlot?: number | null,
): NutritionLogInsert {
  const now = new Date();
  return {
    id,
    user_id: userId,
    method: 'TYPED',
    logged_at: now.toISOString(), recorded_date: localDate(now),
    description: description.trim() || null,
    protein_g: parsed.protein_g,
    carbs_g: parsed.carbs_g,
    fat_g: parsed.fat_g,
    calories: parsed.calories,
    ...(mealSlot != null ? { meal_slot: mealSlot } : {}),
  };
}

export { hasAnyMacro, parseQuickEntry };
